    /**
     * Dissect the specified absolute path.
     * @param path the path to dissect.
     * @return String[] {root, remaining path}.
     * @throws java.lang.NullPointerException if path is null.
     * @since Ant 1.7
     */
    public String[] dissect(String path) {
        char sep = File.separatorChar;
        path = normalizeSeparators(path, sep);

        if (!isAbsolutePath(path)) {
            throw new BuildException(path + " is not an absolute path");
        }

        if (isDosOrNetwarePath(path, sep)) {
            return dissectDosOrNetwarePath(path, sep);
        }

        if (isUncPath(path, sep)) {
            return dissectUncPath(path, sep);
        }

        return new String[] {File.separator, path.substring(1)};
    }

    private static String normalizeSeparators(String path, char sep) {
        return path.replace('/', sep).replace('\\', sep);
    }

    private static boolean isDosOrNetwarePath(String path, char sep) {
        return (ON_DOS || ON_NETWARE) && path.indexOf(':') > 0;
    }

    private String[] dissectDosOrNetwarePath(String path, char sep) {
        int colon = path.indexOf(':');
        int next = colon + 1;
        String root = path.substring(0, next) + sep;

        int start = (path.charAt(next) == sep) ? next + 1 : next;
        String remainingPath = removeConsecutiveSlashes(path.substring(start), sep);

        return new String[] {root, remainingPath};
    }

    private static String removeConsecutiveSlashes(String path, char sep) {
        if (path.isEmpty()) {
            return path;
        }

        StringBuilder sb = new StringBuilder();
        char prevChar = path.charAt(0);
        sb.append(prevChar);

        for (int i = 1; i < path.length(); i++) {
            char currentChar = path.charAt(i);
            if (currentChar != sep || prevChar != sep) {
                sb.append(currentChar);
            }
            prevChar = currentChar;
        }

        return sb.toString();
    }

    private static boolean isUncPath(String path, char sep) {
        return path.length() > 1 && path.charAt(1) == sep;
    }

    private String[] dissectUncPath(String path, char sep) {
        int firstSep = path.indexOf(sep, 2);
        if (firstSep == -1) {
            return new String[] {path, ""};
        }

        int secondSep = path.indexOf(sep, firstSep + 1);
        if (secondSep == -1) {
            return new String[] {path, ""};
        }

        String root = path.substring(0, secondSep + 1);
        String remaining = path.substring(secondSep + 1);
        return new String[] {root, remaining};
    }
