    protected static void hbMakeCodeLengths(char[] len, int[] freq,
                                            int alphaSize, int maxLen) {
        final int[] heap = new int[MAX_ALPHA_SIZE * 2];
        final int[] weight = new int[MAX_ALPHA_SIZE * 2];
        final int[] parent = new int[MAX_ALPHA_SIZE * 2];

        for (int i = alphaSize; --i >= 0;) {
            weight[i + 1] = (freq[i] == 0 ? 1 : freq[i]) << 8;
        }

        for (boolean tooLong = true; tooLong;) {
            tooLong = false;
            buildHeap(heap, weight, parent, alphaSize);
            buildHuffmanTree(heap, weight, parent, alphaSize);
            assignCodeLengths(len, parent, alphaSize, maxLen, tooLong);
            if (tooLong) {
                reduceWeights(weight, alphaSize);
            }
        }
    }

    private static void buildHeap(int[] heap, int[] weight, int[] parent,
                                  int alphaSize) {
        int nHeap = 0;
        heap[0] = 0;
        weight[0] = 0;
        parent[0] = -2;

        for (int i = 1; i <= alphaSize; i++) {
            parent[i] = -1;
            nHeap++;
            heap[nHeap] = i;
            int zz = nHeap;
            int tmp = heap[zz];
            while (weight[tmp] < weight[heap[zz >> 1]]) {
                heap[zz] = heap[zz >> 1];
                zz >>= 1;
            }
            heap[zz] = tmp;
        }
    }

    private static void buildHuffmanTree(int[] heap, int[] weight, int[] parent,
                                         int alphaSize) {
        int nNodes = alphaSize;
        int nHeap = alphaSize;

        while (nHeap > 1) {
            int n1 = extractMin(heap, weight, nHeap);
            nHeap--;
            int n2 = extractMin(heap, weight, nHeap);
            nHeap--;

            nNodes++;
            parent[n1] = parent[n2] = nNodes;
            weight[nNodes] = ((weight[n1] & 0xffffff00) + (weight[n2] & 0xffffff00))
                | (1 + (((weight[n1] & 0x000000ff) > (weight[n2] & 0x000000ff))
                        ? (weight[n1] & 0x000000ff) : (weight[n2] & 0x000000ff)));
            parent[nNodes] = -1;
            nHeap++;
            heap[nHeap] = nNodes;

            int tmp = heap[nHeap];
            int zz = nHeap;
            while (weight[tmp] < weight[heap[zz >> 1]]) {
                heap[zz] = heap[zz >> 1];
                zz >>= 1;
            }
            heap[zz] = tmp;
        }
    }

    private static int extractMin(int[] heap, int[] weight, int nHeap) {
        int n1 = heap[1];
        heap[1] = heap[nHeap];

        int zz = 1;
        int tmp = heap[1];
        while (true) {
            int yy = zz << 1;
            if (yy > nHeap) {
                break;
            }
            if ((yy < nHeap) && (weight[heap[yy + 1]] < weight[heap[yy]])) {
                yy++;
            }
            if (weight[tmp] < weight[heap[yy]]) {
                break;
            }
            heap[zz] = heap[yy];
            zz = yy;
        }
        heap[zz] = tmp;
        return n1;
    }

    private static void assignCodeLengths(char[] len, int[] parent, int alphaSize,
                                          int maxLen, boolean tooLongFlag) {
        for (int i = 1; i <= alphaSize; i++) {
            int j = 0;
            int k = i;
            for (int parentK; (parentK = parent[k]) >= 0;) {
                k = parentK;
                j++;
            }
            len[i - 1] = (char) j;
            if (j > maxLen) {
                tooLongFlag = true;
            }
        }
    }

    private static void reduceWeights(int[] weight, int alphaSize) {
        for (int i = 1; i < alphaSize; i++) {
            int j = weight[i] >> 8;
            j = 1 + (j >> 1);
            weight[i] = j << 8;
        }
    }
