protected void addPathFile(File pathComponent) throws IOException {
    if (!pathComponents.contains(pathComponent)) {
        pathComponents.addElement(pathComponent);
    }

    if (pathComponent.isDirectory()) {
        return;
    }

    String classpath = getManifestClasspath(pathComponent);
    if (!"".equals(classpath)) {
        processManifestClasspath(pathComponent, classpath);
    }
}

/**
 * Retrieves the classpath from the manifest of the given JAR file.
 * Returns empty string if no manifest or no CLASSPATH attribute.
 *
 * @param pathComponent the JAR file to inspect
 * @return the manifest classpath value, or "" if none
 * @throws IOException if reading the JAR fails
 */
private String getManifestClasspath(File pathComponent) throws IOException {
    String absPathPlusTimeAndLength = pathComponent.getAbsolutePath()
            + pathComponent.lastModified() + "-" + pathComponent.length();
    String cached = (String) pathMap.get(absPathPlusTimeAndLength);
    if (cached != null) {
        return cached;
    }

    JarFile jarFile = null;
    try {
        jarFile = new JarFile(pathComponent);
        Manifest manifest = jarFile.getManifest();
        if (manifest == null) {
            return "";
        }
        String classpath = manifest.getMainAttributes()
                .getValue(Attributes.Name.CLASS_PATH);
        if (classpath == null) {
            classpath = "";
        }
        pathMap.put(absPathPlusTimeAndLength, classpath);
        return classpath;
    } finally {
        if (jarFile != null) {
            jarFile.close();
        }
    }
}

/**
 * Processes each manifest classpath entry and adds referenced libraries.
 *
 * @param jarFile the original JAR file
 * @param manifestClasspath the manifest CLASS_PATH attribute
 * @throws IOException if a referenced library's file cannot be processed
 */
private void processManifestClasspath(File jarFile, String manifestClasspath) throws IOException {
    URL baseURL = FILE_UTILS.getFileURL(jarFile);
    StringTokenizer st = new StringTokenizer(manifestClasspath);
    while (st.hasMoreTokens()) {
        String classpathElement = st.nextToken();
        URL libraryURL = new URL(baseURL, classpathElement);
        if (!libraryURL.getProtocol().equals("file")) {
            log("Skipping jar library " + classpathElement
                    + " since only relative URLs are supported by this" + " loader",
                    Project.MSG_VERBOSE);
            continue;
        }
        String decodedPath = Locator.decodeUri(libraryURL.getFile());
        File libraryFile = new File(decodedPath);
        if (libraryFile.exists() && !isInPath(libraryFile)) {
            addPathFile(libraryFile);
        }
    }
}

