        || JAVAC16.equalsIgnoreCase(impl)
        || JAVAC15.equalsIgnoreCase(impl)
        || JAVAC14.equalsIgnoreCase(impl)
        || JAVAC13.equalsIgnoreCase(impl)
        || MODERN.equalsIgnoreCase(impl);
