public Object buildConnection(Object elementType, Object fromElement,
        Object fromStyle, Object toElement, Object toStyle,
        Object unidirectional, Object namespace)
    throws IllegalModelElementConnectionException {

    if (!isConnectionValid(elementType, fromElement, toElement, true)) {
        throw new IllegalModelElementConnectionException("Cannot make a "
                + elementType.getClass().getName() + " between a "
                + fromElement.getClass().getName() + " and a "
                + toElement.getClass().getName());
    }

    Object connection = null;
    boolean uni = (unidirectional instanceof Boolean)
        ? ((Boolean) unidirectional).booleanValue() : false;

    // Build lookup table for element types to dispatcher lambdas
    // Using function interfaces to defer execution and avoid early evaluation
    Map<Object, UmlConnectionFactory> connectionFactories =
        new HashMap<Object, UmlConnectionFactory>();

    connectionFactories.put(metaTypes.getAssociation(),
        () -> getCore().buildAssociation(fromElement,
                fromStyle, toElement,
                toStyle, uni));
    connectionFactories.put(metaTypes.getAssociationEnd(),
        () -> {
            if (fromElement instanceof UmlAssociation) {
                return getCore().buildAssociationEnd(toElement, fromElement);
            } else if (fromElement instanceof Classifier) {
                return getCore().buildAssociationEnd(fromElement, toElement);
            }
            return null;
        });
    connectionFactories.put(metaTypes.getAssociationClass(),
        () -> getCore().buildAssociationClass(fromElement, toElement));
    connectionFactories.put(metaTypes.getAssociationRole(),
        () -> getCollaborations().buildAssociationRole(fromElement,
                fromStyle, toElement, toStyle,
                ((Boolean) unidirectional).booleanValue()));
    connectionFactories.put(metaTypes.getGeneralization(),
        () -> getCore().buildGeneralization(fromElement, toElement));
    connectionFactories.put(metaTypes.getPackageImport(),
        () -> getCore().buildPackageImport(fromElement, toElement));
    connectionFactories.put(metaTypes.getUsage(),
        () -> getCore().buildUsage(fromElement, toElement));
    connectionFactories.put(metaTypes.getDependency(),
        () -> getCore().buildDependency(fromElement, toElement));
    connectionFactories.put(metaTypes.getAbstraction(),
        () -> getCore().buildRealization(fromElement, toElement, namespace));
    connectionFactories.put(metaTypes.getLink(),
        () -> getCommonBehavior().buildLink(fromElement, toElement));
    connectionFactories.put(metaTypes.getExtend(),
        () -> getUseCases().buildExtend(toElement, fromElement)); // Note reversal
    connectionFactories.put(metaTypes.getInclude(),
        () -> getUseCases().buildInclude(fromElement, toElement));
    connectionFactories.put(metaTypes.getTransition(),
        () -> getStateMachines().buildTransition(fromElement, toElement));

    UmlConnectionFactory factory = connectionFactories.get(elementType);
    if (factory != null) {
        connection = factory.build();
    }

    if (connection == null) {
        throw new IllegalModelElementConnectionException("Cannot make a "
                + elementType.getClass().getName() + " between a "
                + fromElement.getClass().getName() + " and a "
                + toElement.getClass().getName());
    }

    return connection;
}

