        Classifier classifier = extractClassifier(context);
        if (classifier != null) {
            Feature result = findOperationInClassifier(classifier, opname);
            if (result != null) {
                return result;
            }
        }

        Namespace pack = extractNamespace(context, classifier);
        if (pack != null) {
            return findOperationInPackage(pack, opname);
        }

        return null;
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
}

private Classifier extractClassifier(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

private Feature findOperationInClassifier(Classifier classifier, String opname) {
    for (Feature f : classifier.getFeature()) {
        if (f instanceof Operation && opname.equals(f.getName())) {
            return f;
        }
    }
    return null;
}

private Namespace extractNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier != null) {
        return findTopLevelNamespace(classifier.getNamespace());
    }
    return null;
}

private Namespace findTopLevelNamespace(Namespace ns) {
    Namespace parent = ns;
    while (parent instanceof Classifier && parent.getNamespace() != null) {
        parent = parent.getNamespace();
    }
    return parent instanceof Namespace ? parent : null;
}

private Object findOperationInPackage(Namespace pack, String opname) {
    for (ModelElement me : pack.getOwnedElement()) {
        if (me instanceof Classifier) {
            Feature result = findOperationInClassifier((Classifier) me, opname);
            if (result != null) {
                return result;
            }
        }
    }
    return null;
}

