def insert(self, position, newChild):
    if self._is_string_like_and_not_navigable(newChild):
        newChild = NavigableString(newChild)

    position = min(position, len(self.contents))
    if self._has_parent_and_is_not_orphan(newChild):
        self._handle_inserting_existing_child(newChild, position)

    newChild.parent = self
    previousChild = None
    if position == 0:
        newChild.previousSibling = None
        newChild.previous = self
    else:
        previousChild = self.contents[position-1]
        newChild.previousSibling = previousChild
        newChild.previousSibling.nextSibling = newChild
        newChild.previous = previousChild._lastRecursiveChild()
    if newChild.previous:
        newChild.previous.next = newChild

    newChildsLastElement = newChild._lastRecursiveChild()

    if position >= len(self.contents):
        self._setup_last_element_for_append(newChildsLastElement)
    else:
        self._setup_last_element_for_insert(newChild, newChildsLastElement, position)

    if newChildsLastElement.next:
        newChildsLastElement.next.previous = newChildsLastElement
    self.contents.insert(position, newChild)

def _is_string_like_and_not_navigable(self, newChild):
    """Check if newChild is string-like but not a NavigableString."""
    return (isinstance(newChild, basestring)
            or isinstance(newChild, unicode)) \
           and not isinstance(newChild, NavigableString)

def _has_parent_and_is_not_orphan(self, newChild):
    """Check if newChild has a parent and is not an orphan."""
    return hasattr(newChild, 'parent') and newChild.parent != None

def _handle_inserting_existing_child(self, newChild, position):
    """Handle insertion of an element that is already a child."""
    if newChild.parent == self:
        index = self.find(newChild)
        if index and index < position:
            position = position - 1
    newChild.extract()

def _setup_last_element_for_append(self, lastElement):
    """Set up next/prev pointers when appending at the end."""
    parent = self
    parentsNextSibling = None
    while not parentsNextSibling:
        parentsNextSibling = parent.nextSibling
        parent = parent.parent
        if not parent:
            break
    if parentsNextSibling:
        lastElement.next = parentsNextSibling
    else:
        lastElement.next = None

def _setup_last_element_for_insert(self, newChild, lastElement, position):
    """Set up next/prev pointers when inserting in the middle."""
    nextChild = self.contents[position]
    newChild.nextSibling = nextChild
    if newChild.nextSibling:
        newChild.nextSibling.previousSibling = newChild
    lastElement.next = nextChild

def append(self, tag):
    """Appends the given tag to the contents of this tag."""
    self.insert(len(self.contents), tag)

