def _process_object(el, attribs):
    """Process attributes of an <object> element and its related attributes."""
    codebase = None
    if 'codebase' in attribs:
        codebase = el.get('codebase')
        yield (el, 'codebase', codebase, 0)
    for attrib in ('classid', 'data'):
        if attrib in attribs:
            value = el.get(attrib)
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, attrib, value, 0)
    if 'archive' in attribs:
        for match in _archive_re.finditer(el.get('archive')):
            value = match.group(0)
            if codebase is not None:
                value = urljoin(codebase, value)
            yield (el, 'archive', value, match.start())


def _process_regular_element(el, attribs, link_attrs):
    """Process all link attributes on regular (non-object) elements."""
    for attr in attribs:
        if attr in link_attrs:
            yield (el, attr, attribs[attr], 0)


def _process_style_tag_links(el):
    """Process CSS links found in a <style> tag's text content."""
    for match in _css_url_re.finditer(el.text):
        yield (el, None, match.group(1), match.start(1))
    for match in _css_import_re.finditer(el.text):
        yield (el, None, match.group(1), match.start(1))


def _process_inline_style_links(el):
    """Process CSS links found in an element's inline 'style' attribute."""
    for match in _css_url_re.finditer(el.get('style')):
        yield (el, 'style', match.group(1), match.start(1))

