def has_scheme_and_valid_namespace(scheme, prefixes):
    if scheme is None:
        return False
    p, sep, r = scheme.partition(':')
    if not is_valid_scheme_prefix_and_rest(p, r):
        return False
    ns = prefixes.get(p)
    return bool(ns)


