def insert(self, position, newChild):
    if self._should_convert_to_navigable_string(newChild):
        newChild = NavigableString(newChild)

    position = min(position, len(self.contents))
    if self._is_already_child(newChild):
        self._handle_reinsertion(position, newChild)

    newChild.parent = self
    self._setup_new_child_relations(position, newChild)
    self._attach_to_tree(position, newChild)
    self.contents.insert(position, newChild)

def _should_convert_to_navigable_string(self, newChild):
    """Converts strings and unicode to NavigableString if needed."""
    return (isinstance(newChild, basestring) or isinstance(newChild, unicode)) \
           and not isinstance(newChild, NavigableString)

def _is_already_child(self, newChild):
    """Checks if newChild is a child of this element."""
    return hasattr(newChild, 'parent') and newChild.parent is not None

def _handle_reinsertion(self, position, newChild):
    """Handles inserting a child already belonging to this element."""
    if newChild.parent == self:
        index = self.find(newChild)
        if index is not None and index < position:
            position -= 1
    newChild.extract()

def _setup_new_child_relations(self, position, newChild):
    """Sets up sibling/previous/next relations for the new child."""
    if position == 0:
        newChild.previousSibling = None
        newChild.previous = self
    else:
        previousChild = self.contents[position - 1]
        newChild.previousSibling = previousChild
        previousChild.nextSibling = newChild
        newChild.previous = previousChild._lastRecursiveChild()

    if newChild.previous:
        newChild.previous.next = newChild

def _attach_to_tree(self, position, newChild):
    """Attaches the new child into the parse tree correctly."""
    lastElement = newChild._lastRecursiveChild()

    if position >= len(self.contents):
        self._attach_at_end(lastElement)
    else:
        nextChild = self.contents[position]
        newChild.nextSibling = nextChild
        if nextChild:
            nextChild.previousSibling = newChild
        lastElement.next = nextChild
        if lastElement.next:
            lastElement.next.previous = lastElement

def _attach_at_end(self, lastElement):
    """Handles attachment logic when inserting at the end."""
    parent = self
    next_sibling = None
    while not next_sibling and parent:
        next_sibling = parent.nextSibling
        parent = parent.parent

    if next_sibling:
        lastElement.next = next_sibling
        next_sibling.previous = lastElement
    else:
        lastElement.next = None

def properties_for_id_with_scheme(item_id, prefixes, refines):
    if not item_id:
        return {}

    ans = {}

    for elem in refines[item_id]:
        key = elem.get('property')
        if not key:
            continue

        val = (elem.text or '').strip()
        if not val:
            continue

        scheme = elem.get('scheme') or None
        scheme_ns = None

        if scheme is not None:
            p, _, r = scheme.partition(':')
            if p and r:
                ns = prefixes.get(p)
                if ns:
                    scheme_ns = ns
                    scheme = r

        ans[key] = (scheme_ns, scheme, val)

    return ans

