@Override
public boolean commit() throws LoginException {
  if (LOG.isDebugEnabled()) {
    LOG.debug("hadoop login commit");
  }

  if (!subject.getPrincipals(User.class).isEmpty()) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("using existing subject:" + subject.getPrincipals());
    }
    return true;
  }

  Principal user = findUser();
  if (user == null) {
    user = findEnvironmentOrSystemUser();
  }
  if (user == null) {
    user = getCanonicalUser(OS_PRINCIPAL_CLASS);
    if (LOG.isDebugEnabled()) {
      LOG.debug("using local user:" + user);
    }
  }

  if (user != null) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Using user: \"" + user + "\" with name " + user.getName());
    }

    User userEntry = newUserEntry(user.getName());
    if (LOG.isDebugEnabled()) {
      LOG.debug("User entry: \"" + userEntry.toString() + "\"");
    }

    subject.getPrincipals().add(userEntry);
    return true;
  }

  LOG.error("Can't find user in " + subject);
  throw new LoginException("Can't find user name");
}

private Principal findUser() throws LoginException {
  if (isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
    Principal user = getCanonicalUser(KerberosPrincipal.class);
    if (LOG.isDebugEnabled()) {
      LOG.debug("using kerberos user:" + user);
    }
    return user;
  }
  return null;
}

private Principal findEnvironmentOrSystemUser() {
  if (!isSecurityEnabled()) {
    String envUser = System.getenv(HADOOP_USER_NAME);
    if (envUser == null) {
      envUser = System.getProperty(HADOOP_USER_NAME);
    }
    return envUser == null ? null : new User(envUser);
  }
  return null;
}

private User newUserEntry(String userName) throws LoginException {
  try {
    return new User(userName);
  } catch (Exception e) {
    throw (LoginException) (new LoginException(e.toString()).initCause(e));
  }
}

}

@Override
public boolean commit() throws LoginException {
  if (LOG.isDebugEnabled()) {
    LOG.debug("hadoop login commit");
  }

  if (hasUserInSubject()) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("using existing subject:" + subject.getPrincipals());
    }
    return true;
  }

  Principal user = findUserFromKerberos();
  if (user == null && !isSecurityEnabled()) {
    user = findUserFromEnvironmentOrSystemProperties();
  }
  if (user == null) {
    user = findUserFromOSPrincipal();
  }

  if (user != null) {
    return addUserToSubject(user);
  }

  LOG.error("Can't find user in " + subject);
  throw new LoginException("Can't find user name");
}

private boolean hasUserInSubject() {
  return !subject.getPrincipals(User.class).isEmpty();
}

private Principal findUserFromKerberos() {
  if (!isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
    return null;
  }
  Principal user = getCanonicalUser(KerberosPrincipal.class);
  if (LOG.isDebugEnabled() && user != null) {
    LOG.debug("using kerberos user:" + user);
  }
  return user;
}

private Principal findUserFromEnvironmentOrSystemProperties() {
  String envUser = System.getenv(HADOOP_USER_NAME);
  if (envUser == null) {
    envUser = System.getProperty(HADOOP_USER_NAME);
  }
  return envUser == null ? null : new User(envUser);
}

private Principal findUserFromOSPrincipal() {
  Principal user = getCanonicalUser(OS_PRINCIPAL_CLASS);
  if (LOG.isDebugEnabled() && user != null) {
    LOG.debug("using local user:" + user);
  }
  return user;
}

private boolean addUserToSubject(Principal user) throws LoginException {
  if (LOG.isDebugEnabled()) {
    LOG.debug("Using user: \"" + user + "\" with name " + user.getName());
  }

  User userEntry;
  try {
    userEntry = new User(user.getName());
  } catch (Exception e) {
    throw (LoginException)(new LoginException(e.toString()).initCause(e));
  }

  if (LOG.isDebugEnabled()) {
    LOG.debug("User entry: \"" + userEntry.toString() + "\"");
  }

  subject.getPrincipals().add(userEntry);
  return true;
}

