private List<LocatedBlock> getFinalizedBlockRange(long offset, long length) throws IOException {
    synchronized(infoLock) {
      assert (locatedBlocks != null) : "locatedBlocks is null";
      List<LocatedBlock> blockRange = new ArrayList<LocatedBlock>();
      int blockIdx = locatedBlocks.findBlock(offset);
      if (blockIdx < 0) {
        blockIdx = LocatedBlocks.getInsertIndex(blockIdx);
      }
      long remaining = length;
      long curOff = offset;
      while(remaining > 0) {
        LocatedBlock blk = getBlockIfCached(locatedBlocks, blockIdx);
        if (blk == null || curOff < blk.getStartOffset()) {
          fetchAndInsertBlocks(curOff, remaining);
          continue;
        }
        assert curOff >= blk.getStartOffset() : "Block not found";
        blockRange.add(blk);
        long bytesRead = blk.getStartOffset() + blk.getBlockSize() - curOff;
        remaining -= bytesRead;
        curOff += bytesRead;
        blockIdx++;
      }
      return blockRange;
    }
  }

  private LocatedBlock getBlockIfCached(LocatedBlocks blocks, int index) {
    if (index < 0 || index >= blocks.locatedBlockCount()) {
      return null;
    }
    return blocks.get(index);
  }

  private void fetchAndInsertBlocks(long offset, long length) throws IOException {
    LocatedBlocks newBlocks = dfsClient.getLocatedBlocks(src, offset, length);
    if (newBlocks == null) {
