/**
 * Find the best matching datanode for the given DatanodeID by searching
 * rack-local or random nodes when the exact match is not found.
 *
 * @param dnId the datanode ID to match
 * @return the best matching DatanodeDescriptor, or null if none found
 */
private DatanodeDescriptor findBestMatchingDatanode(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

  List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);
  if (rackNodes == null || rackNodes.isEmpty()) {
    return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
  }

  // Try machine-local first
  for (Node rackNode : rackNodes) {
    DatanodeDescriptor descriptor = (DatanodeDescriptor) rackNode;
    if (descriptor.getIpAddr().equals(dnId.getIpAddr())) {
      return descriptor;
    }
  }

  // Fall back to rack-local random
  return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
}

