/**
 * Fallback logic to find a matching datanode descriptor when direct lookup fails.
 * First tries machine-local datanode in the resolved rack, then rack-local random,
 * and finally any node in the cluster.
 *
 * @param dnId DatanodeID constructed from the address string
 * @return DatanodeDescriptor found via fallback logic, or null if none found
 */
private DatanodeDescriptor findBestMatchFallback(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);

  List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);
  if (rackNodes != null) {
    DatanodeDescriptor node = findMachineLocalNode(rackNodes, dnId.getIpAddr());
    if (node == null) {
      node = findRandomRackLocalNode(rackNodes);
    }
    if (node != null) {
      return node;
    }
  }

  // Fall back to any node in the cluster
  return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
}

/**
 * Search for a node in the given rack that matches the target IP address.
 *
 * @param rackNodes list of nodes in the rack
 * @param targetIp target IP address to match
 * @return DatanodeDescriptor with matching IP, or null if none found
 */
private DatanodeDescriptor findMachineLocalNode(List<Node> rackNodes, String targetIp) {
  for (Node rackNode : rackNodes) {
    DatanodeDescriptor dd = (DatanodeDescriptor) rackNode;
    if (dd.getIpAddr().equals(targetIp)) {
      return dd;
    }
  }
  return null;
}

