/**
 * Helper method to find a datanode using lookup context built from address parsing.
 * Tries machine local first, then rack local, then random.
 *
 * @param context context object containing DatanodeID, topology, and rack path
 * @return found DatanodeDescriptor or null if none found
 */
private DatanodeDescriptor findDatanodeByLookupContext(DatanodeDescriptorLookupContext context) {
  DatanodeDescriptor node = null;
  List<Node> rackNodes = context.networkTopology.getDatanodesInRack(context.networkLocation);
  if (rackNodes != null) {
    for (Node rackNode : rackNodes) {
      if (((DatanodeDescriptor) rackNode).getIpAddr().equals(context.dnId.getIpAddr())) {
        node = (DatanodeDescriptor) rackNode;
        break;
      }
    }
    if (node == null && !rackNodes.isEmpty()) {
      node = (DatanodeDescriptor) (rackNodes
          .get(DFSUtil.getRandom().nextInt(rackNodes.size())));
    }
  }
  if (node == null) {
    node = (DatanodeDescriptor) context.networkTopology
        .chooseRandom(NodeBase.ROOT);
  }
  return node;
}

