private boolean tryAddProxyNodesInSameRack(DatanodeInfo targetDN) {
  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN) && addTo(loc)) {
      return true;
    }
  }
  return false;
}

/**
 * Try to add any non-busy replica as a proxy source.
 * @return true if a suitable proxy was found and added; false otherwise
 */
private boolean tryAddNonBusyProxy() {
  for (StorageGroup loc : block.getLocations()) {
    if (addTo(loc)) {
      return true;
    }
  }
  return false;
}

/**
 * Choose a proxy source.
 * 
 * @return true if a proxy is found; otherwise false
 */
private boolean chooseProxySource() {
  final DatanodeInfo targetDN = target.getDatanodeInfo();
  // if source and target are same nodes then no need of proxy
  if (source.getDatanodeInfo().equals(targetDN) && addTo(source)) {
    return true;
  }
  // if node group is supported, first try add nodes in the same node group
  if (cluster.isNodeGroupAware()) {
    final StorageGroup sameNodeGroupProxy = findProxyInNodeGroup(targetDN);
    if (sameNodeGroupProxy != null && addTo(sameNodeGroupProxy)) {
      return true;
    }
  }
  // check if there is replica which is on the same rack with the target
  final StorageGroup sameRackProxy = findProxyOnSameRack(targetDN);
  if (sameRackProxy != null && addTo(sameRackProxy)) {
    return true;
  }
  // find out a non-busy replica
  for (StorageGroup loc : block.getLocations()) {
    if (addTo(loc)) {
      return true;
    }
  }
  return false;
}

/**
 * Finds a proxy StorageGroup located on the same node group as the target.
 * Only considered if node groups are enabled.
 */
private StorageGroup findProxyInNodeGroup(final DatanodeInfo targetDN) {
  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameNodeGroup(loc.getDatanodeInfo(), targetDN)) {
      return loc;
    }
  }
  return null;
}

/**
 * Finds a proxy StorageGroup located on the same rack as the target.
 */
private StorageGroup findProxyOnSameRack(final DatanodeInfo targetDN) {
  for (StorageGroup loc : block.getLocations()) {
    if (cluster.isOnSameRack(loc.getDatanodeInfo(), targetDN)) {
      return loc;
    }
  }
  return null;
}

