     *
     * @param baseDir the directory to validate. Must not be null.
     * @throws BuildException if the file does not exist or is not a directory.
     */
    private void validateBaseDirectory(File baseDir) throws BuildException {
        File normalizedBaseDir = FILE_UTILS.normalize(baseDir.getAbsolutePath());
        if (!normalizedBaseDir.exists()) {
            throw new BuildException("Basedir " + normalizedBaseDir.getAbsolutePath()
                + " does not exist");
