     */
    private void setupBaseDirectory(File baseDir) throws BuildException {
        this.baseDir = FILE_UTILS.normalize(baseDir.getAbsolutePath());
        setPropertyInternal(MagicNames.PROJECT_BASEDIR, this.baseDir.getPath());
        String msg = "Project base dir set to: " + this.baseDir;
        log(msg, MSG_VERBOSE);
