    Step step = createStartupProgressStep(in);
    prog.setTotal(Phase.LOADING_EDITS, step, numTxns);
    Counter counter = prog.getCounter(Phase.LOADING_EDITS, step);
    long lastLogTime = monotonicNow();
    long lastInodeId = fsNamesys.dir.getLastInodeId();

    try {
      while (true) {
        try {
          FSEditLogOp op = readOpSafely(in, expectedTxId, recentOpcodeOffsets, numEdits, recovery);
          if (op == null) {
            break;
          }

          verifyTransactionId(op, expectedTxId, recovery);
          applyAndPostProcessOp(op, fsDir, startOpt, in.getVersion(true), lastInodeId,
              counter, prog, step, opCounts, expectedStartingTxId, numTxns, lastLogTime, recentOpcodeOffsets,
              in, numEdits, recovery, toAddRetryCache -> fsNamesys.hasRetryCache() && op.hasRpcIds());

          numEdits++;
          totalEdits++;
        } catch (RollingUpgradeOp.RollbackException e) {
          LOG.info("Stopped at OP_START_ROLLING_UPGRADE for rollback.");
          break;
        } catch (MetaRecoveryContext.RequestStopException e) {
          MetaRecoveryContext.LOG.warn("Stopped reading edit log at " +
              in.getPosition() + "/"  + in.length());
          break;
        }
      }
    } finally {
      fsNamesys.dir.resetLastInodeId(lastInodeId);
      if(closeOnExit) {
        in.close();
      }
      fsDir.writeUnlock();
      fsNamesys.writeUnlock();

      if (LOG.isTraceEnabled()) {
        LOG.trace("replaying edit log finished");
      }

      if (FSImage.LOG.isDebugEnabled()) {
        dumpOpCounts(opCounts);
      }
    }
    return numEdits;
  }

  private FSEditLogOp readOpSafely(EditLogInputStream in, long expectedTxId,
      long[] recentOpcodeOffsets, long numEdits, MetaRecoveryContext recovery)
      throws IOException {
    FSEditLogOp op;
    try {
      op = in.readOp();
      if (op == null) {
        return null;
      }
    } catch (Throwable e) {
      check203UpgradeFailure(in.getVersion(true), e);
      String errorMessage = formatEditLogReplayError(in, recentOpcodeOffsets, expectedTxId);
      FSImage.LOG.error(errorMessage, e);
      if (recovery == null) {
        throw new EditLogInputException(errorMessage, e, numEdits);
      }
      MetaRecoveryContext.editLogLoaderPrompt(
          "We failed to read txId " + expectedTxId,
          recovery, "skipping the bad section in the log");
      in.resync();
      return readOpSafely(in, expectedTxId, recentOpcodeOffsets, numEdits, recovery);
    }
    recentOpcodeOffsets[(int)(numEdits % recentOpcodeOffsets.length)] = in.getPosition();
    return op;
  }

  private void verifyTransactionId(FSEditLogOp op, long expectedTxId,
      MetaRecoveryContext recovery) {
    if (op.hasTransactionId()) {
      if (op.getTransactionId() > expectedTxId) { 
        MetaRecoveryContext.editLogLoaderPrompt("There appears " +
            "to be a gap in the edit log.  We expected txid " +
            expectedTxId + ", but got txid " +
            op.getTransactionId() + ".", recovery, "ignoring missing " +
            " transaction IDs");
      } else if (op.getTransactionId() < expectedTxId) { 
        MetaRecoveryContext.editLogLoaderPrompt("There appears " +
            "to be an out-of-order edit in the edit log.  We " +
            "expected txid " + expectedTxId + ", but got txid " +
            op.getTransactionId() + ".", recovery,
            "skipping the out-of-order edit");
      }
    }
  }

  private void applyAndPostProcessOp(FSEditLogOp op, FSDirectory fsDir,
      StartupOption startOpt, int logVersion, long lastInodeId,
      Counter counter, StartupProgress prog, Step step,
      EnumMap<FSEditLogOpCodes, Holder<Integer>> opCounts,
      long expectedStartingTxId, long numTxns, long lastLogTime,
      long[] recentOpcodeOffsets, EditLogInputStream in, long numEdits,
      MetaRecoveryContext recovery, java.util.function.BooleanSupplier hasRetryCacheSupplier) throws IOException {
    boolean toAddRetryCache = hasRetryCacheSupplier.getAsBoolean();
    long inodeId = applyEditLogOp(op, fsDir, startOpt, logVersion, lastInodeId);
    if (lastInodeId < inodeId) {
      fsNamesys.dir.resetLastInodeId(inodeId);
    }

    try {
      // Apply edit log operation
      applyEditLogOpInternal(op, fsDir, startOpt, logVersion, lastInodeId, inodeId);
    } catch (RollingUpgradeOp.RollbackException e) {
      throw e;
    } catch (Throwable e) {
      LOG.error("Encountered exception on operation " + op, e);
      if (recovery == null) {
        throw e instanceof IOException? (IOException)e: new IOException(e);
      }

      MetaRecoveryContext.editLogLoaderPrompt("Failed to " +
       "apply edit log operation " + op + ": error " +
       e.getMessage(), recovery, "applying edits");
    }

    incrOpCount(op.opCode, opCounts, step, counter);
    if (op.hasTransactionId()) {
      lastAppliedTxId = op.getTransactionId();
      long now = monotonicNow();
      if (now - lastLogTime > REPLAY_TRANSACTION_LOG_INTERVAL) {
        long deltaTxId = lastAppliedTxId - expectedStartingTxId + 1;
        int percent = Math.round((float) deltaTxId / numTxns * 100);
        LOG.info("replaying edit log: " + deltaTxId + "/" + numTxns
            + " transactions completed. (" + percent + "%)");
        lastLogTime = now;
      }
    } else {
      lastAppliedTxId = expectedStartingTxId;
    }

    if (toAddRetryCache) {
      processRetryCacheEntry(op);
    }
  }

  private long applyEditLogOpInternal(FSEditLogOp op, FSDirectory fsDir,
      StartupOption startOpt, int logVersion, long lastInodeId, long inodeId)
      throws IOException {
    return applyEditLogOp(op, fsDir, startOpt, logVersion, lastInodeId);
  }

  private void processRetryCacheEntry(FSEditLogOp op) throws IOException {
    switch (op.opCode) {
    case OP_ADD:
      processRetryCacheForAdd((AddCloseOp) op);
      break;
    case OP_APPEND:
      processRetryCacheForAppend((AppendOp) op);
      break;
    case OP_UPDATE_BLOCKS:
      processRetryCacheForUpdateBlocks((UpdateBlocksOp) op);
      break;
    case OP_CONCAT_DELETE:
      fsNamesys.addCacheEntry(((ConcatDeleteOp) op).rpcClientId,
          ((ConcatDeleteOp) op).rpcCallId);
      break;
    case OP_RENAME_OLD:
      fsNamesys.addCacheEntry(((RenameOldOp) op).rpcClientId,
          ((RenameOldOp) op).rpcCallId);
      break;
    case OP_DELETE:
      fsNamesys.addCacheEntry(((DeleteOp) op).rpcClientId,
          ((DeleteOp) op).rpcCallId);
      break;
    case OP_CREATE_SNAPSHOT:
      processRetryCacheForCreateSnapshot((CreateSnapshotOp) op);
      break;
    case OP_DELETE_SNAPSHOT:
      fsNamesys.addCacheEntry(((DeleteSnapshotOp) op).rpcClientId,
          ((DeleteSnapshotOp) op).rpcCallId);
      break;
    case OP_RENAME_SNAPSHOT:
      fsNamesys.addCacheEntry(((RenameSnapshotOp) op).rpcClientId,
          ((RenameSnapshotOp) op).rpcCallId);
      break;
    case OP_GET_DELEGATION_TOKEN:
      fsNamesys.getDelegationTokenSecretManager()
          .addPersistedDelegationToken(((GetDelegationTokenOp) op).token,
              ((GetDelegationTokenOp) op).expiryTime);
      break;
    case OP_RENEW_DELEGATION_TOKEN:
      fsNamesys.getDelegationTokenSecretManager()
          .updatePersistedTokenRenewal(((RenewDelegationTokenOp) op).token,
              ((RenewDelegationTokenOp) op).expiryTime);
      break;
    case OP_CANCEL_DELEGATION_TOKEN:
      fsNamesys.getDelegationTokenSecretManager()
          .updatePersistedTokenCancellation(((CancelDelegationTokenOp) op).token);
      break;
    case OP_UPDATE_MASTER_KEY:
      fsNamesys.getDelegationTokenSecretManager()
          .updatePersistedMasterKey(((UpdateMasterKeyOp) op).key);
      break;
    case OP_REASSIGN_LEASE:
      processRetryCacheForReassignLease((ReassignLeaseOp) op);
      break;
    case OP_ADD_CACHE_DIRECTIVE:
      processRetryCacheForAddCacheDirective((AddCacheDirectiveInfoOp) op);
      break;
    case OP_MODIFY_CACHE_DIRECTIVE:
      fsNamesys.addCacheEntry(((ModifyCacheDirectiveInfoOp) op).rpcClientId,
          ((ModifyCacheDirectiveInfoOp) op).rpcCallId);
      break;
    case OP_REMOVE_CACHE_DIRECTIVE:
      fsNamesys.addCacheEntry(((RemoveCacheDirectiveInfoOp) op).rpcClientId,
          ((RemoveCacheDirectiveInfoOp) op).rpcCallId);
      break;
    case OP_ADD_CACHE_POOL:
      fsNamesys.addCacheEntry(((AddCachePoolOp) op).rpcClientId,
          ((AddCachePoolOp) op).rpcCallId);
      break;
    case OP_MODIFY_CACHE_POOL:
      fsNamesys.addCacheEntry(((ModifyCachePoolOp) op).rpcClientId,
          ((ModifyCachePoolOp) op).rpcCallId);
      break;
    case OP_REMOVE_CACHE_POOL:
      fsNamesys.addCacheEntry(((RemoveCachePoolOp) op).rpcClientId,
          ((RemoveCachePoolOp) op).rpcCallId);
      break;
    case OP_SET_ACL:
      break;
    case OP_SET_XATTR:
      fsNamesys.addCacheEntry(((SetXAttrOp) op).rpcClientId,
          ((SetXAttrOp) op).rpcCallId);
      break;
    case OP_REMOVE_XATTR:
      fsNamesys.addCacheEntry(((RemoveXAttrOp) op).rpcClientId,
          ((RemoveXAttrOp) op).rpcCallId);
      break;
    default:
      break;
    }
  }

  private void processRetryCacheForAdd(AddCloseOp op) throws IOException {
    String path = renameReservedPathsOnUpgrade(op.path, op.logVersion);
    HdfsFileStatus stat = FSDirStatAndListingOp.createFileStatus(fsNamesys.dir, path,
        HdfsFileStatus.EMPTY_NAME, null, BlockStoragePolicySuite.ID_UNSPECIFIED,
        Snapshot.CURRENT_STATE_ID, false, null);
    fsNamesys.addCacheEntryWithPayload(op.rpcClientId, op.rpcCallId, stat);
  }

  private void processRetryCacheForAppend(AppendOp op) throws IOException {
    String path = renameReservedPathsOnUpgrade(op.path, op.logVersion);
    LocatedBlock lb = fsNamesys.prepareFileForAppend(path, null,
        op.clientName, op.clientMachine, op.newBlock, false, false);
    HdfsFileStatus stat = FSDirStatAndListingOp.createFileStatus(fsNamesys.dir, path,
        HdfsFileStatus.EMPTY_NAME, null, BlockStoragePolicySuite.ID_UNSPECIFIED,
        Snapshot.CURRENT_STATE_ID, false, null);
    fsNamesys.addCacheEntryWithPayload(op.rpcClientId, op.rpcCallId,
        new LastBlockWithStatus(lb, stat));
  }

  private void processRetryCacheForUpdateBlocks(UpdateBlocksOp op) {
    fsNamesys.addCacheEntry(op.rpcClientId, op.rpcCallId);
  }

  private void processRetryCacheForCreateSnapshot(CreateSnapshotOp op) throws IOException {
    final String snapshotRoot = renameReservedPathsOnUpgrade(op.snapshotRoot, op.logVersion);
    String path = fsNamesys.getSnapshotManager().createSnapshot(null, snapshotRoot, op.snapshotName);
    fsNamesys.addCacheEntryWithPayload(op.rpcClientId, op.rpcCallId, path);
  }

  private void processRetryCacheForReassignLease(ReassignLeaseOp op) throws IOException {
    final String path = renameReservedPathsOnUpgrade(op.path, op.logVersion);
    INodeFile pendingFile = fsDir.getINode(path).asFile();
    Lease lease = fsNamesys.leaseManager.getLease(op.leaseHolder);
    fsNamesys.reassignLeaseInternal(lease, path, op.newHolder, pendingFile);
  }

  private void processRetryCacheForAddCacheDirective(AddCacheDirectiveInfoOp op) {
    CacheDirectiveInfo result = fsNamesys.getCacheManager().addDirectiveFromEditLog(op.directive);
    Long id = result.getId();
    fsNamesys.addCacheEntryWithPayload(op.rpcClientId, op.rpcCallId, id);
  }

class Dumper implements Runnable {
    /** Dump data into a file */
    private void dump() {
      // Create dump outputstream for the first time
      if (dumpOut == null) {
        createDumpOutputStream();
      }

      // Get raf for the first dump
      if (raf == null) {
        openRandomAccessFileForDump();
      }

      if (LOG.isDebugEnabled()) {
        LOG.debug("Start dump. Before dump, nonSequentialWriteInMemory == "
            + nonSequentialWriteInMemory.get());
      }

      dumpPendingWrites();

      if (LOG.isDebugEnabled()) {
        LOG.debug("After dump, nonSequentialWriteInMemory == "
            + nonSequentialWriteInMemory.get());
      }
    }

    private void createDumpOutputStream() {
      LOG.info("Create dump file: " + dumpFilePath);
      File dumpFile = new File(dumpFilePath);
      try {
        synchronized (this) {
          // check if alive again
          Preconditions.checkState(dumpFile.createNewFile(),
              "The dump file should not exist: %s", dumpFilePath);
          dumpOut = new FileOutputStream(dumpFile);
        }
      } catch (IOException e) {
        LOG.error("Got failure when creating dump stream " + dumpFilePath, e);
        enabledDump = false;
        closeDumpOutputStreamQuietly();
      }
    }

    private void closeDumpOutputStreamQuietly() {
      if (dumpOut != null) {
        try {
          dumpOut.close();
        } catch (IOException e1) {
          LOG.error("Can't close dump stream " + dumpFilePath, e1);
        }
      }
    }

    private void openRandomAccessFileForDump() {
      try {
        raf = new RandomAccessFile(dumpFilePath, "r");
      } catch (FileNotFoundException e) {
        LOG.error("Can't get random access to file " + dumpFilePath);
        // Disable dump
        enabledDump = false;
      }
    }

    private void dumpPendingWrites() {
      Iterator<OffsetRange> it = pendingWrites.keySet().iterator();
      while (activeState && it.hasNext()
          && nonSequentialWriteInMemory.get() > 0) {
        OffsetRange key = it.next();
        WriteCtx writeCtx = pendingWrites.get(key);
        if (writeCtx == null) {
          // This write was just deleted
          continue;
        }
        try {
          long dumpedDataSize = writeCtx.dumpData(dumpOut, raf);
          if (dumpedDataSize > 0) {
            updateNonSequentialWriteInMemory(-dumpedDataSize);
          }
        } catch (IOException e) {
          LOG.error("Dump data failed: " + writeCtx + " with error: " + e
              + " OpenFileCtx state: " + activeState);
          // Disable dump
          enabledDump = false;
          return;
        }
      }
    }

    @Override
    public void run() {
      while (activeState && enabledDump) {
        try {
          if (nonSequentialWriteInMemory.get() >= DUMP_WRITE_WATER_MARK) {
            dump();
          }
          synchronized (OpenFileCtx.this) {
            if (nonSequentialWriteInMemory.get() < DUMP_WRITE_WATER_MARK) {
              OpenFileCtx.this.notifyAll();
              try {
                OpenFileCtx.this.wait();
                if (LOG.isDebugEnabled()) {
                  LOG.debug("Dumper woke up");
                }
              } catch (InterruptedException e) {
                LOG.info("Dumper is interrupted, dumpFilePath= "
                    + OpenFileCtx.this.dumpFilePath);
              }
            }
          }
          if (LOG.isDebugEnabled()) {
            LOG.debug("Dumper checking OpenFileCtx activeState: " + activeState
                + " enabledDump: " + enabledDump);
          }
        } catch (Throwable t) {
          // unblock threads with new request
          synchronized (OpenFileCtx.this) {
            OpenFileCtx.this.notifyAll();
          }
          LOG.info("Dumper get Throwable: " + t + ". dumpFilePath: "
              + OpenFileCtx.this.dumpFilePath, t);
          activeState = false;
        }
      }
    }
  }

