private static boolean isAsciiEscapedCharInList(char ch) {
    return "nrt".indexOf(ch) != -1;
}

private static char resolveAsciiEscChar(char ch) {
    switch (ch) {
        case 'n':
            return '\n';
        case 'r':
            return '\r';
        case 't':
            return '\t';
        default:
            return 0;
    }
}

private static int resolvePosixID(char ch, IntConsumer negationConsumer) {
    boolean[] negate = { false };
    int posixID;

    switch (ch) {
        case 'D':
            negate[0] = true;
        case 'd':
            posixID = RETokenPOSIX.DIGIT;
            break;
        case 'S':
            negate[0] = true;
        case 's':
            posixID = RETokenPOSIX.SPACE;
            break;
        case 'W':
            negate[0] = true;
        case 'w':
            posixID = RETokenPOSIX.ALNUM;
            break;
        default:
            return -1;
    }

    negationConsumer.accept(negate[0] ? 1 : 0);
    return posixID;
}

