public Object clone() throws CloneNotSupportedException {
    StandardChartTheme clone = (StandardChartTheme) super.clone();
    if (this.drawingSupplier instanceof PublicCloneable) {
        PublicCloneable pc = (PublicCloneable) this.drawingSupplier;
        try {
            clone.drawingSupplier = (DrawingSupplier) pc.clone();
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    } else if (this.drawingSupplier != null) {
        // Fallback: create new instance using reflection if needed, but
        // current usage assumes PublicCloneable or DefaultDrawingSupplier
        clone.drawingSupplier = this.drawingSupplier;
    }

    // Deep copy transient Paint fields only if they are serializable (not needed here)
    // All other fields are immutable or shared (e.g., BarPainter, XYBarPainter).
    // Preserving original behavior: clone of Paint and Stroke fields not performed.
    // ShadowGenerator is not cloneable and must be null or shared.

    return clone;
}

