            strio.seek(new_off)
            continue
        label = readPrecisely(strio, l)
        self._appendLabel(label)

def _validateCompressionOffset(self, new_off, visited):
    """Check for compression loop and update visited set."""
    if new_off in visited:
        return False
    visited.add(new_off)
    return True

def _appendLabel(self, label):
    """Append a DNS label to the current name."""
    if self.name == b'':
        self.name = label
    else:
        self.name = self.name + b'.' + label

"""
A version of first order predicate logic, built on
top of the typed lambda calculus.
"""
from __future__ import print_function, unicode_literals

import re
